/**
 * Test that inverse cumulative probability density calculations match expected values.
 *
 * <p>Note: Any expected values outside the support of the distribution are ignored.
 */
@ParameterizedTest
@MethodSource
final void testInverseCumulativeProbability(ContinuousDistribution dist, double[] points, double[] values, DoubleTolerance tolerance) {
    final double lower = dist.getSupportLowerBound();
    final double upper = dist.getSupportUpperBound();
    for (int i = 0; i < points.length; i++) {
        final double x = values[i];
        if (x < lower || x > upper) {
            continue;
        }
        final double p = points[i];
        TestUtils.assertEquals(x, dist.inverseCumulativeProbability(p), tolerance, () -> "Incorrect inverse cumulative probability value returned for " + p);
    }
}

